def transform(grid):
    out=[row[:] for row in grid]
    # Color 1 endpoints determine diagonal(s); color 6 is a second diagonal line color.
    pts={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v not in (1,6): pts.setdefault(v,[]).append((r,c))
    for color, ps in pts.items():
        for i,(r1,c1) in enumerate(ps):
            for r2,c2 in ps[i+1:]:
                if abs(r2-r1)==abs(c2-c1) and r2!=r1:
                    dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
                    for k in range(1,abs(r2-r1)):
                        out[r1+dr*k][c1+dc*k]=color
    # 6 markers are connected along a diagonal too, possibly as a ray through the line.
    six=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==6]
    for i,(r1,c1) in enumerate(six):
        for r2,c2 in six[i+1:]:
            if abs(r2-r1)==abs(c2-c1) and r2!=r1:
                dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
                for k in range(1,abs(r2-r1)):
                    out[r1+dr*k][c1+dc*k]=6
    return out
